<script setup>
import { Head } from '@inertiajs/vue3';
import { computed, ref } from 'vue';
const props = defineProps({ brand:Object, owner:Object, credentials:Array, dashboardUrl:String });
const copied = ref('');
const all = computed(() => props.credentials.map(item => `${item.name} (${item.role})\nاسم الدخول: ${item.username}\nكلمة المرور: ${item.password}`).join('\n\n'));
async function copy(value,key){await navigator.clipboard.writeText(value);copied.value=key;setTimeout(()=>{if(copied.value===key)copied.value=''},1800)}
</script>
<template><Head :title="`تم تجهيز ${brand.name}`"/><main class="page"><section class="card"><header><span class="mark"><i class="bi bi-check2"></i></span><small>اكتمل التجهيز بنجاح</small><h1>{{ brand.name }} جاهز للعمل</h1><p>احفظ بيانات الفريق قبل الانتقال إلى لوحة التحكم.</p></header><div class="owner"><i class="bi bi-person-badge"></i><div><small>حساب المالك</small><strong>{{owner.name}}</strong><span>اسم الدخول: <bdi>{{owner.username}}</bdi></span></div></div><section v-if="credentials.length" class="creds"><div class="heading"><div><small>تظهر مرة واحدة</small><h2>بيانات دخول الفريق</h2></div><button @click="copy(all,'all')"><i :class="copied==='all'?'bi bi-check2':'bi bi-copy'"></i>{{copied==='all'?'تم النسخ':'نسخ الكل'}}</button></div><article v-for="(item,index) in credentials" :key="item.username"><div class="person"><span>{{item.name.charAt(0)}}</span><p><strong>{{item.name}}</strong><small>{{item.role}}</small></p></div><dl><div><dt>اسم الدخول</dt><dd><bdi>{{item.username}}</bdi></dd></div><div><dt>كلمة المرور</dt><dd><bdi>{{item.password}}</bdi></dd></div></dl><button :aria-label="`نسخ بيانات ${item.name}`" @click="copy(`${item.username}\n${item.password}`,index)"><i :class="copied===index?'bi bi-check2':'bi bi-copy'"></i></button></article></section><div class="security"><i class="bi bi-shield-lock"></i><div><strong>سلّم كل حساب لصاحبه فقط.</strong><span>اطلب تغيير كلمات المرور بعد أول دخول. لن تظهر هذه البيانات مرة أخرى.</span></div></div><a class="dashboard" :href="dashboardUrl">دخول إلى لوحة التحكم <i class="bi bi-arrow-left"></i></a></section></main></template>
<style scoped>*{box-sizing:border-box}.page{display:grid;min-height:100dvh;place-items:center;padding:1rem;color:var(--brand);background:var(--canvas)}.card{width:min(100%,710px);padding:clamp(1.2rem,4vw,2.1rem);border:1px solid var(--line);border-radius:12px;background:var(--surface);box-shadow:none;border-top:4px solid var(--brand)}.card>header{text-align:center}.mark{display:grid;width:62px;height:62px;margin:0 auto .65rem;place-items:center;border-radius:12px;color:var(--brand);background:var(--brand-soft);font-size:1.75rem}.card header>small{color:var(--brand);font-size:.875rem;font-weight:800}.card h1{margin:.28rem 0;font-size:clamp(1.4rem,4vw,1.9rem)}.card header p{margin:0;color:var(--muted);font-size:.875rem;line-height:1.8}.owner{display:flex;align-items:center;gap:.6rem;margin-top:1.1rem;padding:.75rem;border:1px solid var(--line);border-radius:12px;background:var(--canvas)}.owner>i{display:grid;width:40px;height:40px;place-items:center;border-radius:11px;color:var(--brand);background:var(--canvas)}.owner div,.person p{display:grid}.owner small,.heading small{color:var(--muted);font-size:.875rem}.owner strong{font-size:.875rem}.owner span{font-size:.875rem}.creds{margin-top:.9rem}.heading{display:flex;align-items:center;justify-content:space-between;margin-bottom:.5rem}.heading h2{margin:.08rem 0;font-size:.875rem}.heading button{min-height:40px;padding:0 .6rem;border:1px solid var(--line);border-radius:8px;color:var(--brand);background:var(--canvas);font:inherit;font-size:.875rem;font-weight:800}.creds article{display:grid;grid-template-columns:1fr 1.2fr 40px;align-items:center;gap:.55rem;padding:.65rem;border:1px solid var(--line);border-radius:12px}.creds article+article{margin-top:.4rem}.person{display:flex;align-items:center;gap:.45rem}.person>span{display:grid;width:34px;height:34px;place-items:center;border-radius:10px;color:#FFFDFA;background:var(--brand);font-weight:800}.person p{margin:0}.person strong{font-size:.875rem}.person small{color:var(--muted);font-size:.875rem}.creds dl{display:grid;margin:0;grid-template-columns:1fr 1fr;gap:.35rem}.creds dl div{display:grid;padding:.35rem;border-radius:8px;background:var(--canvas)}.creds dt{color:var(--muted);font-size:.875rem}.creds dd{margin:0;font-size:.875rem;font-weight:800;overflow-wrap:anywhere}.creds article>button{display:grid;width:40px;height:40px;place-items:center;border:1px solid var(--line);border-radius:8px;color:var(--brand);background:var(--surface)}.security{display:flex;gap:.55rem;margin-top:.9rem;padding:.7rem;border:1px solid var(--accent);border-radius:12px;color:#6c5424;background:var(--canvas)}.security div{display:grid}.security strong{font-size:.875rem}.security span{font-size:.875rem;line-height:1.65}.dashboard{display:flex;min-height:48px;align-items:center;justify-content:center;gap:.35rem;margin-top:.9rem;border-radius:8px;color:#FFFDFA;background:var(--brand);font-size:.875rem;font-weight:800;text-decoration:none}@media(max-width:600px){.page{padding:0}.card{min-height:100dvh;border:0;border-radius:0}.creds article{grid-template-columns:1fr 40px}.creds dl{grid-column:1/-1;grid-row:2}.creds article>button{grid-column:2;grid-row:1}.dashboard{position:sticky;bottom:.7rem}}
/* Operational layout and responsive hierarchy. */
.page{place-items:start center;padding:40px 20px;color:var(--ink)}.card{width:min(100%,900px);padding:0;border:1px solid var(--line);border-radius:12px;overflow:hidden}.card>header{text-align:start;padding:26px 28px;border-bottom:1px solid var(--line);display:grid;grid-template-columns:48px 1fr;column-gap:16px;align-items:center}.mark{grid-column:1;grid-row:1/4;width:48px;height:48px;margin:0;border-radius:8px}.card header>small,.card header>h1,.card header>p{grid-column:2}.card h1{font-size:26px;color:var(--ink)}.owner{margin:20px 28px;border-radius:8px}.creds{margin:22px 28px}.heading{padding-bottom:14px;border-bottom:1px solid var(--line)}.heading h2{font-size:20px}.creds article{grid-template-columns:1fr 1.3fr 44px;padding:16px 0;border:0;border-bottom:1px solid var(--line);border-radius:0}.creds dl div{padding:10px;border-radius:6px}.security{margin:20px 28px;border-radius:6px}.dashboard{margin:0;padding:20px 28px;border-radius:0;min-height:64px;font-size:16px}@media(max-width:600px){.page{padding:16px 12px}.card{min-height:0;border:1px solid var(--line);border-radius:10px}.card>header{padding:22px 18px}.card h1{font-size:22px}.owner,.creds,.security{margin:18px}.creds article{grid-template-columns:1fr 44px}.dashboard{position:static}}
</style>
